-- Fase 8: os serviços saem do código e vão para o banco. O diretor cria e edita no hub
-- (dados, perguntas técnicas da diagnóstica, roteiro por slide) e anexa a apresentação em HTML,
-- que fica no Workers KV (APRESENTACOES). Nada é apagado: o que sai fica inativo.
CREATE TABLE servicos (
  id TEXT PRIMARY KEY,
  ordem INTEGER NOT NULL,
  nome TEXT NOT NULL,
  sigla TEXT NOT NULL,
  resumo TEXT NOT NULL DEFAULT '',
  dores TEXT NOT NULL DEFAULT '[]',
  entregamos TEXT NOT NULL DEFAULT '[]',
  fica_com_cliente TEXT NOT NULL DEFAULT '[]',
  ancora_valor TEXT NOT NULL DEFAULT '',
  situacao TEXT NOT NULL DEFAULT 'ativo' CHECK (situacao IN ('ativo', 'em_estruturacao', 'inativo')),
  perguntas TEXT NOT NULL DEFAULT '[]',
  -- JSON (SlideDoRoteiro[]); NULL = o roteiro padrão.
  roteiro TEXT,
  -- JSON (ArquivoDaApresentacao); NULL = sem apresentação própria.
  apresentacao TEXT,
  -- Só cresce: cada envio ganha um número novo, mesmo depois de remover.
  apresentacao_versao INTEGER NOT NULL DEFAULT 0,
  atualizado_em TEXT NOT NULL DEFAULT (datetime('now')),
  -- Nome de quem salvou por último (sem chave estrangeira: é só registro).
  atualizado_por TEXT
);

-- O que a apresentação em HTML contou ao hub na reunião (dores marcadas, etapa do preço, calculadora).
ALTER TABLE reunioes ADD COLUMN interacoes TEXT;

-- Os 12 da carta de serviços (compartilhado/dados/servicos-completos.ts, sem mudar um texto).
INSERT INTO servicos (id, ordem, nome, sigla, resumo, dores, entregamos, fica_com_cliente, ancora_valor, situacao, perguntas) VALUES
('desenvolvimento-de-produto', 1, 'Desenvolvimento de Produto', 'DP', 'Máquinas e equipamentos do zero, adaptação, nacionalização ou melhoria.', '["Processo manual, lento ou com risco para o operador","Equipamento importado caro ou sem peça de reposição","Ideia de produto sem projeto para fabricar","Máquina que não acompanha mais a produção"]', '["Modelagem CAD 3D","Desenhos 2D para fabricação","Simulações, quando aplicável","Lista de componentes","Manual de montagem"]', '["Fabricação e montagem física, pelo cliente ou por parceiros"]', 'projeto de máquina com escritório de engenharia ou engenheiro sênior', 'ativo', '[{"id":"dp-funcao","bloco":"escopo","tipo":"texto","texto":"O que a máquina ou o produto precisa fazer? Qual é a entrada e a saída do processo?"},{"id":"dp-tipo","bloco":"escopo","tipo":"opcoes","texto":"É do zero, adaptação, nacionalização ou melhoria de algo que já existe?","opcoes":["Do zero","Adaptação","Nacionalização","Melhoria"]},{"id":"dp-capacidade","bloco":"parametros","tipo":"curto","texto":"Qual capacidade esperada? (peças por hora, carga, dimensões)"},{"id":"dp-referencias","bloco":"escopo","tipo":"texto","texto":"Tem fotos, vídeos, desenhos ou uma máquina de referência?","dica":"Peça para mandar no WhatsApp logo depois da reunião."},{"id":"dp-normas","bloco":"escopo","tipo":"curto","texto":"Precisa atender alguma norma? (NR-12, alimentícia, outra)"},{"id":"dp-automacao","bloco":"parametros","tipo":"opcoes","texto":"Vai precisar de automação (acionamento hidráulico, pneumático, sensores)?","opcoes":["Sim","Não","Não sabe"],"dica":"Adicional de +20% na v4."},{"id":"dp-simulacao","bloco":"parametros","tipo":"opcoes","texto":"Precisa de simulação de resistência, fadiga ou térmica?","opcoes":["Sim","Não","Não sabe"],"dica":"Adicional de +20% na v4."},{"id":"dp-prototipo","bloco":"parametros","tipo":"opcoes","texto":"Vai querer um protótipo para validar antes de produzir?","opcoes":["Sim","Não","Não sabe"],"dica":"Se sim, inclua também Prototipagem."},{"id":"dp-fabricacao","bloco":"escopo","tipo":"curto","texto":"Quem vai fabricar? Já tem serralheria, usinagem ou fornecedor?","dica":"Antecipa a objeção \"vocês fabricam?\"."}]'),
('desenho-tecnico', 2, 'Desenho Técnico', 'DT', 'Desenhos 2D e modelos 3D de produtos novos ou por engenharia reversa de peças físicas.', '["Peça que só um fornecedor faz, e sem desenho","Desenhos antigos, à mão ou desatualizados","Peça importada com prazo longo de reposição","Fabricante pedindo desenho para orçar"]', '["Desenhos 2D padronizados, com tolerâncias e medidas","Modelagem 3D","Arquivos conforme ABNT e ISO"]', '["Fabricação das peças a partir dos arquivos"]', 'desenho técnico com projetista ou escritório de engenharia', 'ativo', '[{"id":"dt-pecas","bloco":"parametros","tipo":"numero","texto":"Quantas peças ou conjuntos?"},{"id":"dt-folhas","bloco":"parametros","tipo":"numero","texto":"Estimativa de folhas de desenho","dica":"R$ 90 por folha na v4. Se o cliente não souber, Projetos estima."},{"id":"dt-reversa","bloco":"escopo","tipo":"opcoes","texto":"Existe peça física para medir (engenharia reversa)?","opcoes":["Sim","Não"]},{"id":"dt-finalidade","bloco":"escopo","tipo":"curto","texto":"Para que vai usar os desenhos? (fabricar, cotar, documentar, manutenção)"},{"id":"dt-formato","bloco":"escopo","tipo":"curto","texto":"Em que formato precisa dos arquivos? (PDF, DWG, STEP)"},{"id":"dt-complexidade","bloco":"parametros","tipo":"opcoes","texto":"Complexidade","opcoes":["Fácil","Normal","Complexo"]}]'),
('prototipagem', 3, 'Prototipagem e Validação Experimental', 'PT', 'Testar o funcionamento mecânico antes da produção em escala.', '["Medo de investir na produção sem saber se funciona","Produto que falha em uso e ninguém sabe por quê","Ajuste caro depois que o lote ou o molde está pronto"]', '["Protótipo funcional","Relatórios de validação","Diagnóstico de falhas","Ajustes no projeto"]', '["Produção em escala"]', 'desenvolvimento de protótipo com empresa de engenharia', 'ativo', '[{"id":"pt-validar","bloco":"escopo","tipo":"texto","texto":"O que exatamente precisa ser validado? (funcionamento, resistência, durabilidade)"},{"id":"pt-projeto","bloco":"escopo","tipo":"opcoes","texto":"Já existe projeto ou desenho do produto?","opcoes":["Sim","Não","Parcial"],"dica":"Se não existir, comece por Desenvolvimento de Produto."},{"id":"pt-quantidade","bloco":"parametros","tipo":"numero","texto":"Quantos protótipos ou iterações?"},{"id":"pt-materiais","bloco":"parametros","tipo":"curto","texto":"Materiais e processos previstos (entram como custos diretos)"},{"id":"pt-ensaios","bloco":"escopo","tipo":"curto","texto":"Que ensaio ou critério de aprovação o cliente espera?"}]'),
